import random
import base64
import struct
from typing import List

# We generate interesting, yet valid Base64-encoded strings that cover:
# - Different decoded lengths (including boundary lengths around 1,2,3 bytes and multiples of 3)
# - Proper padding variants (= and ==)
# - No padding variant where allowed
# - Inclusion of all 64 alphabet characters across different cases
# - Long and short inputs, up to a cap (<=4096 bytes encoded)
# - Chunked forms with and without newlines (some decoders accept both)
# - Different content classes (all-zero, all-FF, ASCII text, UTF-8 text, structured binary headers)
# The output is a bytes object that is ASCII Base64 text.

_B64_ALPHABET = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _structured_binary(rng: random.Random, n: int) -> bytes:
    # Create a binary blob with a simple header and mixed content to test decoders downstream.
    # [magic(4)="SIMD"][version(1)][flags(1)][len(2)][payload]
    magic = b"SIMD"
    version = rng.randrange(0, 256)
    flags = rng.randrange(0, 256)
    # Ensure length fits and at least some payload
    max_payload = max(0, n - 8)
    payload_len = max_payload if max_payload <= 65535 else 65535
    payload = _rand_bytes(rng, payload_len)
    header = magic + bytes([version, flags]) + struct.pack(">H", payload_len)
    return (header + payload)[:n]


def _ascii_text(rng: random.Random, n: int) -> bytes:
    # Generate readable ASCII text (letters, digits, punctuation, spaces, newlines)
    alphabet = (b"The quick brown fox jumps over the lazy dog 0123456789 \n\t,:;.!?-_/+()[]{}<>\"'" )
    return bytes(rng.choice(alphabet) for _ in range(n))


def _utf8_text(rng: random.Random, n: int) -> bytes:
    # Generate valid UTF-8 by sampling common blocks and ASCII
    blocks: List[range] = [
        range(0x20, 0x7F),           # ASCII printable
        range(0x00A0, 0x0100),       # Latin-1 supplement
        range(0x0400, 0x0460),       # Cyrillic subset
        range(0x4E00, 0x4F00),       # CJK subset
        range(0x0370, 0x03A0),       # Greek subset
    ]
    out = bytearray()
    while len(out) < n:
        block = rng.choice(blocks)
        cp = rng.choice(list(block))
        ch = chr(cp)
        enc = ch.encode('utf-8')
        if len(out) + len(enc) > n:
            break
        out += enc
    # pad to exact length with spaces if short
    if len(out) < n:
        out += b' ' * (n - len(out))
    return bytes(out)


def _patterned_bytes(rng: random.Random, n: int) -> bytes:
    # Patterns to create repeated data stressing run-lengths
    patterns = [
        b"\x00", b"\xFF", b"\xAA", b"\x55",
        b"\x00\xFF", b"\xFF\x00", b"\xAA\x55", b"\x55\xAA",
        b"ABC", b"\x00ABC\xFF", b"\x01\x02\x03\x04",
    ]
    pat = rng.choice(patterns)
    reps = (n + len(pat) - 1) // len(pat)
    data = (pat * reps)[:n]
    return data


def _choose_content(rng: random.Random, length: int) -> bytes:
    # Select among several content generators
    choices = [
        (0.20, lambda: _rand_bytes(rng, length)),
        (0.15, lambda: _patterned_bytes(rng, length)),
        (0.20, lambda: _ascii_text(rng, length)),
        (0.15, lambda: _utf8_text(rng, length)),
        (0.30, lambda: _structured_binary(rng, length)),
    ]
    t = rng.random()
    acc = 0.0
    for p, fn in choices:
        acc += p
        if t <= acc:
            return fn()
    return _rand_bytes(rng, length)


def _maybe_insert_newlines(rng: random.Random, b64: bytes) -> bytes:
    # Optionally wrap lines at 64/76 chars or random widths
    mode = rng.randrange(0, 4)
    if mode == 0:
        return b64  # no newlines
    if mode == 1:
        width = 76
    elif mode == 2:
        width = 64
    else:
        width = rng.randrange(32, 121)  # arbitrary wrap
    out = bytearray()
    for i in range(0, len(b64), width):
        out += b64[i:i+width]
        if i + width < len(b64):
            out += b"\n"
    return bytes(out)


def _encode_with_padding_variant(rng: random.Random, raw: bytes) -> bytes:
    # Standard base64 encoding first
    b64 = base64.b64encode(raw)
    # Optionally remove padding when legal (len%3 != 0 requires padding to decode strictly,
    # but many decoders tolerate missing padding). We keep it valid by sometimes retaining padding.
    mode = rng.randrange(0, 3)
    if mode == 0:
        return b64  # keep padding
    # Try trimming one or two '=' only when present
    if b64.endswith(b'==') and mode == 1:
        # produce variant without padding (still many decoders accept this)
        return b64[:-2]
    if b64.endswith(b'=') and mode >= 1:
        return b64[:-1]
    return b64


def _encode_urlsafe_variant(rng: random.Random, raw: bytes) -> bytes:
    # Occasionally use URL-safe alphabet, which some decoders support as well. It is still valid Base64 variant.
    b64 = base64.urlsafe_b64encode(raw)
    # Same padding handling
    mode = rng.randrange(0, 2)
    if mode == 0:
        return b64
    return b64.rstrip(b'=')


def _ensure_valid_base64_bytes(b: bytes) -> bytes:
    # Make sure output only contains Base64 alphabet and newlines
    allowed = set(_B64_ALPHABET) | {ord('\n'), ord('\r')}
    return bytes(ch for ch in b if ch in allowed)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide target decoded length with biases to interesting sizes
    special_lengths = [0, 1, 2, 3, 4, 5, 6, 7, 8, 15, 16, 31, 32, 47, 48, 63, 64, 127, 128, 255, 256, 512, 1023, 1024, 1500, 2048, 3072]
    if rng.random() < 0.7:
        raw_len = rng.choice(special_lengths)
    else:
        raw_len = rng.randrange(0, 3500)  # Leave room for encoding expansion and newlines < 4096

    # Generate raw content
    raw = _choose_content(rng, raw_len)

    # Choose encoding variant
    if rng.random() < 0.15:
        b64 = _encode_urlsafe_variant(rng, raw)
    else:
        b64 = _encode_with_padding_variant(rng, raw)

    # Maybe insert newlines
    b64 = _maybe_insert_newlines(rng, b64)

    # Occasionally prepend or append a full-alphabet block to exercise decoder tables
    if rng.random() < 0.1:
        block = bytes(_B64_ALPHABET)
        # Keep size under limit
        if len(block) + len(b64) < 4000:
            if rng.random() < 0.5:
                b64 = block + b"\n" + b64
            else:
                b64 = b64 + b"\n" + block

    # Ensure within size limit; if too large, trim at a newline boundary if possible
    limit = 4096
    if len(b64) > limit:
        # Try to keep complete lines
        cut = b64.rfind(b"\n", 0, limit)
        if cut == -1:
            b64 = b64[:limit]
        else:
            b64 = b64[:cut]

    # Sanitize to valid alphabet/newlines only (should already be fine)
    b64 = _ensure_valid_base64_bytes(b64)

    # Guarantee non-empty sometimes to avoid trivial empty-case domination
    if len(b64) == 0:
        b64 = b"\n" if rng.random() < 0.5 else base64.b64encode(b"\x00")

    return b64
